from pathlib import Path
import json
R=Path(__file__).parent
def load(p):return json.loads((R/p).read_text(encoding='utf-8-sig'))
def row(path,label,m,n=None):
    d=load(path);methods=d.get('methods',d.get('methods_run',d.get('tests_run',m)));assert methods==m,(label,methods)
    def number(keys,default=0):
        for k in keys:
            if k in d:return len(d[k])if isinstance(d[k],list)else d[k]
        return default
    f=number(['failed_methods','failure_records','failures']);e=number(['error_methods','error_records','errors']);s=number(['skipped','skips']);sub=d.get('subcases',d.get('subtests',n));assert n is None or sub==n,(label,sub)
    return {'suite':label,'methods':m,'passed':m-f-e-s,'failed':f,'errors':e,'skipped':s,'subcases':sub,'actually_executed':True,'result_file':path}
